INSERT INTO public."categories" ("slug", "label", "image", "intro", "sort_order", "created_at", "updated_at") VALUES ('deserts', 'Deserts', 'https://framerusercontent.com/images/8G7eGuuOmijUEO3VXSdPJ9i4VU.png', 'End on a sweet note with warm, indulgent desserts made fresh in-house every day.', 30, '2026-06-08 23:07:53.87796+00', '2026-06-15 21:55:47.517387+00');
INSERT INTO public."categories" ("slug", "label", "image", "intro", "sort_order", "created_at", "updated_at") VALUES ('drinks', 'Drinks', 'https://framerusercontent.com/images/eQS6ke7KFxu839Roxv77gisTY0Y.png', 'Cool down, perk up or treat yourself with a curated lineup of sodas, juices, smoothies and coffee.', 40, '2026-06-08 23:07:53.87796+00', '2026-06-15 21:55:47.517387+00');
INSERT INTO public."categories" ("slug", "label", "image", "intro", "sort_order", "created_at", "updated_at") VALUES ('pasta', 'Pasta', 'https://framerusercontent.com/images/xd9Oo3dlguei8tJ9fP0wq4BtTtE.png', 'Twirl into comfort with our handcrafted pasta — slow-simmered sauces, al dente noodles, and bright, fresh ingredients in every bowl.', 10, '2026-06-08 23:07:53.87796+00', '2026-06-15 21:55:47.517387+00');
INSERT INTO public."categories" ("slug", "label", "image", "intro", "sort_order", "created_at", "updated_at") VALUES ('pizza', 'Pizza', 'https://framerusercontent.com/images/O35ad4eRtufs0gpp6JZXayT5IM.png', 'From the classic simplicity of a traditional Margherita to the rich indulgence of gourmet truffle oil creations, we artfully blend the best of old-world charm with modern culinary innovation. Each pizza is hand-tossed with care, topped with fresh, high-quality ingredients, and baked to golden perfection.', 0, '2026-06-08 23:07:53.87796+00', '2026-06-15 21:55:47.517387+00');
INSERT INTO public."categories" ("slug", "label", "image", "intro", "sort_order", "created_at", "updated_at") VALUES ('sides', 'BBQ', 'https://raw.githubusercontent.com/BonganiCacambile/sweet-lovely-634f24d4/main/Pork%20Ribs.png', 'Flame-grilled, juicy and packed with bold smoky flavour premium BBQ meals made to satisfy every craving.', 20, '2026-06-08 23:07:53.87796+00', '2026-07-23 13:41:11.842648+00');
